export function usePermalink({ room, type, url }: Args): HookResult {
    const resourceId = url ? getPrimaryPermalinkEntity(url) : null;
    const effectiveType = type ?? (resourceId?.[0] === "@"
        ? PillType.UserMention
        : resourceId?.[0] === "!" || resourceId?.[0] === "#"
          ? PillType.RoomMention
          : null);
    const userId = effectiveType === PillType.UserMention && resourceId?.[0] === "@" ? resourceId : null;
    const localMember = userId ? room?.getMember(userId) : null;
    const [profile, setProfile] = useState<Profile | null>(null);

    useEffect(() => {
        if (!userId || localMember) return;
        let active = true;
        MatrixClientPeg.get()
