            },
            resourceId: userId,
            type: effectiveType,
        };
    }

    if (effectiveType === PillType.RoomMention && resourceId && (resourceId[0] === "!" || resourceId[0] === "#")) {
        const client = MatrixClientPeg.get();
        const resolvedRoom = resourceId[0] === "#"
            ? client.getRooms().find((candidate) =>
